        V: AsRef<str>,
    {
        let key: ResponseHeadersKey = key.as_ref().to_owned();
        if self.should_skip_header(&key) {
            return self;
        }
        self.headers
            .entry(key)
            .or_default()
            .push_back(value.as_ref().to_owned());
        self
    }
