            let text: String = serde_json::to_string(&payload)
                .unwrap_or_else(|err: serde_json::Error| format!("{{\"error\":\"{err}\"}}"));
            let content: ToolCallContent = ToolCallContent {
                content: vec![ToolCallResult {
                    r#type: "text".to_owned(),
                    text,
