    let base: &str = config.base_path.trim_end_matches('/');
    let host: &str = config.host.as_str();
    let mut url: String = String::from("https://");
    url.push_str(host);
    url.push_str(base);
    url.push('/');
    url.push_str(trimmed);
    url
}
