///
///     #[response_body(&format!("id: {id:?}, name: {name:?}"))]
///     #[try_get_route_param("id" => id, "name" => name)]
///     async fn handle(self, _: &mut Stream, ctx: &mut Context) -> Status { Status::Continue }
